/**
 * @brief Verifies `.text` opcode parity and `.rodata` jump-table integrity (`0x1949`).
 *        Xác minh tính toàn vẹn mã máy `.text` và bảng nhảy `.rodata` (`0x1949`).
 */
bool VerifyNpthDlBinaryParity() noexcept {
    if (kNpthDlTextWords3461[0] != 0xD503245FU) { // bti c @ 0x2600
        return false;
    }
    // Check ELF magic load at 0x26a4..0x26a8 (`mov w9, #0x457f; movk w9, #0x464c, lsl #16`)
    if (kNpthDlTextWords3461[(0x26a4 - 0x2600) / 4] != 0x5288AFE9U ||
        kNpthDlTextWords3461[(0x26a8 - 0x2600) / 4] != 0x72A8C989U) {
        return false;
    }
    // Check DT_GNU_HASH constant load at 0x4528 (`mov w12, #0xfef5`) and 0x4540 (`movk w12, #0x6fff, lsl #16`)
    if (kNpthDlTextWords3461[(0x4528 - 0x2600) / 4] != 0x529FDEACU ||
        kNpthDlTextWords3461[(0x4540 - 0x2600) / 4] != 0x72ADFFECU) {
        return false;
    }
    return true;
}

